/* GENERATED by mk_sub.py from pair_calc_rule.c (research/h8/rule_exact): option -cube added. Do not edit.
 * Exact class rate of a pin and a class, per outcome, with the part kept by first-stage rules on h1.
 * Research scratch of research/h8/rule_exact, not submitted.
 *
 * The search over the outcomes (tau, eps) of a beta is the one of pair_calc_batch.c (our calculator pair_calc.c with
 * the pruned search of research/h8/counts/mk_pruned.py; set H8_NOCUT=1 for the search of pair_calc.c itself), used
 * here by inclusion and unchanged. For every outcome that passes its necessary conditions:
 *   N3 and, per rule, the number of side-3 solutions whose h1 satisfies the rule: n3r.inc (integers, complete);
 *   E1 = number of side-1 triples (d1, b1, a2): e1_count_big() below, the automaton of e1_exact() in integers;
 *   n3x() of the unchanged code is evaluated beside it (double precision; it may sample) and compared.
 * Output: one line per outcome with a side-3 solution, all counts as decimal integers, so that the sums can be made
 * with exact fractions (rule_tab.py): class rate = sum of E1 * N3 / 2^(3 W - fixed bits of the class).
 *
 *   gcc -O2 -fopenmp -o pair_calc_rule pair_calc_rule.c -lm
 *   ./pair_calc_rule D3 D11 DELTA Y3 ETA BETAFILE Y11 [-rule MASK:V,MASK:V,...]... [-mode auto|orig|proj|both] [-nox]
 *                    [-cappairs LOG2] [-capb LOG2] [-capc LOG2] [-capwork LOG2]
 * The caps only say which of the two exact functions counts an outcome: n3r_orig enumerates the triples
 * (dh1, df1, dh2) and is left out (status 1, nothing counted) when dh1 * df1 exceeds -cappairs, a dh2 list exceeds
 * -capc or the number of triples exceeds -capwork; n3r_proj then counts the outcome. No cap changes a count.
 * BETAFILE: lines "beta [anything]". Rules: up to 8, each a list of conditions "XOR of the bits of h1 in MASK = V".
 * mode auto: n3r_orig, and n3r_proj where the lists of n3r_orig exceed the caps; both: also n3r_proj on every
 * outcome with solutions, compared with n3r_orig.
 * Lines:  OUTR eta beta tau eps E1 n N3 n P n.. S n3status e1status M function X n3x sampled B both Z sizes
 *         BETA beta ...summary...      DONE beta
 */
#define PAIR_CALC_NO_MAIN
#include "pair_calc_batch.c"
#include "n3r.inc"

static void fput_big(FILE *f, big v) {
    char buf[48];
    int n = 0;
    if (v == 0) { fputc('0', f); return; }
    while (v) { buf[n++] = (char)('0' + (int)(v % 10)); v /= 10; }
    while (n) fputc(buf[--n], f);
}

#define E1_CAP (1 << 20)         /* longest list of db1 or dd2 enumerated (the unchanged e1_exact stops at 2^16) */
static double N3X_CAP_WORK = 134217728.0;   /* 2^27: most triples of a full enumeration for which n3x() is evaluated (-capx LOG2) */

/* e1_exact() of pair_calc.c in integers: the number of triples (c1, b1, a2), c1 = Y11 + d1, with b1 ^ b1' = beta that
 * give (tau, eps). Same lists, same automaton. e1_exact() gives a bit u_j that follows d1_j (a2_j prescribed, u_j
 * not) the weight 1/2 for each of its two values; that happens only for j = R3 - 1, read at the last step
 * i = W - 1, where the value of the bit changes neither a condition nor the final sum, so one value with weight 1 is
 * the same count (and the program stops if the case occurs at another step).
 * Returns 0 when counted, -1 when a list is longer than E1_CAP (nothing counted). */
static int e1_count_big(u32 d11, u32 delta, u32 y11, u32 beta, u32 tau, u32 eps, u32 *g_e1a, u32 *g_e1b, big *out) {
    const u32 LOW = LOWBITS;
    u32 x5 = rol(beta, ROT2), nu = ror(tau, ROT3);
    u32 x5m = x5 & LOW, c1v = ~(((d11 + x5) & WMASK) >> 1) & x5m;
    u32 tm = tau & LOW, nm = nu & LOW, em = eps & LOW, um = rol(nm, ROT3);
    Meet m4, m5;
    *out = 0;
    meet_build(&m4, delta, beta, tau);
    meet_build(&m5, d11, nu, eps);
    if (meet_total(&m4) == 0.0 || meet_total(&m5) == 0.0) return 0;
    if (meet_total(&m4) > E1_CAP || meet_total(&m5) > E1_CAP) return -1;
    int na = meet_enum(&m4, g_e1a, E1_CAP), nb = meet_enum(&m5, g_e1b, E1_CAP);
    big total = 0;
    for (int ia = 0; ia < na; ia++) {
        u32 d4 = (delta + g_e1a[ia]) & WMASK;
        u32 a2v = ~(((d4 + tau) & WMASK) >> 1) & tm;
        for (int ib = 0; ib < nb; ib++) {
            u32 dd2 = g_e1b[ib];
            u32 d2v = ~(((dd2 + nu) & WMASK) >> 1) & nm;
            u32 c2v = ~(((d11 + dd2 + eps) & WMASK) >> 1) & em;
            u32 uv = rol(d2v, ROT3);
            big st[2][2] = {{1, 0}, {0, 0}}, nx[2][2];             /* [borrow][carry] */
            for (int i = 0; i < WBITS; i++) {
                nx[0][0] = nx[0][1] = nx[1][0] = nx[1][1] = 0;
                int yb = (y11 >> i) & 1, j = (i + ROT3) % WBITS;
                int ufix = (um >> j) & 1, uval = (uv >> j) & 1;
                int utied = !ufix && ((tm >> j) & 1);
                if (utied && i != WBITS - 1) { fprintf(stderr, "e1_count_big: a tied bit below the last step\n"); exit(3); }
                for (int b = 0; b < 2; b++) for (int k = 0; k < 2; k++) {
                    big v = st[b][k];
                    if (v == 0) continue;
                    for (int c = 0; c < 2; c++) {
                        if (((x5m >> i) & 1) && (int)((c1v >> i) & 1) != c) continue;
                        int d1 = c ^ yb ^ b;
                        if (((tm >> i) & 1) && ((um >> i) & 1) && d1 != (int)(((a2v ^ uv) >> i) & 1)) continue;
                        int bo = ((!c) & yb) | ((!(c ^ yb)) & b);
                        for (int d2 = 0; d2 < 2; d2++) {
                            if (ufix && d2 != uval) continue;
                            if (utied && d2 != 0) continue;
                            int sum = c ^ d2 ^ k;
                            if (((em >> i) & 1) && sum != (int)((c2v >> i) & 1)) continue;
                            int ko = (c & d2) | (c & k) | (d2 & k);
                            nx[bo][ko] += v;
                        }
                    }
                }
                memcpy(st, nx, sizeof st);
            }
            total += st[0][0] + st[0][1] + st[1][0] + st[1][1];
        }
    }
    /* total counts (c1, a2); b1 contributes 2^(W - wt(beta & LOW)) per db1 */
    *out = total << (WBITS - __builtin_popcount(beta & LOW));
    return 0;
}

typedef struct {
    u32 tau, eps;
    big e1, n3, pass[MAXRULE];
    int n3st, e1st, fn;          /* fn 0 = n3r_orig, 1 = n3r_proj */
    double xn; int xsampled;     /* n3x() of the unchanged code; xsampled -1 = not evaluated */
    int both;                    /* -1 not compared, 1 the two functions agree, 0 they differ */
    double e1x;                  /* triples from e1_exact() of the unchanged code (double), -1 = its lists too long */
    double ea, eb, maxnc, keys, surv;
} OutR;
static OutR *g_outr = NULL;
static size_t g_noutr = 0, g_capoutr = 0;
static Scratch g_sc;
static u32 s_xmask = 0, s_xval = 0;   /* the cube: extra fixed bits of e1 and their values (option -cube) */
static int g_sc_ok = 0, g_mode = 0, g_usex = 1;   /* mode 0 auto, 1 orig only, 2 proj only, 3 both */

/* One beta. Returns -1 (eta or beta impossible for D3, D11), -2 (no eps: odd weight) or the number of outcomes that
 * pass the necessary conditions; g_outr[0..g_noutr-1] = the outcomes with a side-3 solution or not counted. */
static long count_beta(u32 d3, u32 d11, u32 delta, u32 y3, u32 y11, u32 eta, u32 beta) {
    g_d3 = d3; g_d11 = d11; g_delta = delta; g_eta = eta; g_beta = beta; g_y11 = y11; g_have_y11 = 1; g_cap = 31;
    g_xmask = 0; g_xval = 0; nouts = 0; ntau = 0; g_neps = 0; g_cut = 0; g_noutr = 0;
    u32 x1 = rol(eta, ROT1), x5 = rol(beta, ROT2);
    if (!in_s(d3, x1) || !in_s(d11, x5)) return -1;
    u32 p = beta ^ ror(eta, ROTD);
    if (__builtin_popcount(p & WMASK) & 1) return -2;
    u32 s = 0;
    for (int i = 0; i < WBITS - 1; i++) if (((s >> i) & 1) ^ ((p >> i) & 1)) s |= 1u << (i + 1);
    g_eps[0] = s; g_eps[1] = s ^ WMASK; g_neps = 2;
    double c0[6] = {0, 0, 1, 0, 0, 0};
    Aut a0;
    aut_init(&a0);
    dfs(0, c0, 0, 0, &a0);
    if (!g_sc_ok) { scratch_init(&g_sc); g_sc_ok = 1; }
    for (size_t i = 0; i < nouts; i++) {
        OutR o;
        memset(&o, 0, sizeof o);
        o.tau = outs[i].tau; o.eps = outs[i].eps; o.both = -1; o.xsampled = -1;
        ResR a, b;
        int have_a = 0, have_b = 0;
        memset(&a, 0, sizeof a); memset(&b, 0, sizeof b);
        if (g_mode != 2) { a = n3r_orig(d3, y3, o.tau, o.eps, eta, s_xmask, s_xval); have_a = 1; }
        /* The unchanged n3x(), for comparison only (no figure uses it). It is evaluated where it takes its
           random-subset branch over the pairs (at most 2^16 pairs times 1024 values of dh2), so that its estimate
           can be reported, and where its full enumeration of the pairs is at most 2^27 triples. Elsewhere (up to
           2^32 triples, minutes to hours for one outcome) it is not evaluated: xsampled stays -1. */
        int x_samples = have_a && (a.na > CAP_LIST || a.nb > CAP_LIST || a.ea * a.eb > PAIR_BUDGET);
        if (g_usex && (!have_a || x_samples || a.xwork <= N3X_CAP_WORK)) {
            u64 rs = 0x243F6A8885A308D3ull ^ ((u64)o.tau << 32) ^ o.eps ^ ((u64)eta << 16);
            Result r = n3x(d3, y3, o.tau, o.eps, eta, &g_sc, &rs, s_xmask, s_xval);
            o.xn = r.n; o.xsampled = r.sampled;
        }
        if (g_mode == 2 || (have_a && a.status != 0 && g_mode != 1) || (g_mode == 3 && a.n > 0)) {
            b = n3r_proj(d3, y3, o.tau, o.eps, eta, s_xmask, s_xval); have_b = 1;
        }
        const ResR *use = (have_a && a.status == 0) ? &a : (have_b ? &b : &a);
        o.fn = (use == &b);
        o.n3 = use->n; o.n3st = use->status;
        for (int r = 0; r < g_nrule; r++) o.pass[r] = use->pass[r];
        o.ea = have_a ? a.ea : b.ea; o.eb = a.eb; o.maxnc = a.maxnc; o.keys = b.keys; o.surv = b.surv;
        if (have_a && a.status == 0 && have_b && b.status == 0) {
            o.both = (a.n == b.n);
            for (int r = 0; r < g_nrule; r++) if (a.pass[r] != b.pass[r]) o.both = 0;
        }
        if (o.n3 == 0 && o.n3st == 0 && !(o.xn > 0.0) && o.both != 0) continue;
        if (g_noutr == g_capoutr) { g_capoutr = g_capoutr ? g_capoutr * 2 : 256; g_outr = realloc(g_outr, g_capoutr * sizeof *g_outr); }
        g_outr[g_noutr++] = o;
    }
    /* side 1 for the listed outcomes: the integer count, and e1_exact() of the unchanged code beside it */
    #pragma omp parallel if (WBITS > 16 && g_noutr > 1)
    {
        u32 *ba = malloc((size_t)E1_CAP * sizeof(u32)), *bb = malloc((size_t)E1_CAP * sizeof(u32));
        u32 *xa = malloc(CAP_LIST * sizeof(u32)), *xb = malloc(CAP_LIST * sizeof(u32));
        #pragma omp for schedule(dynamic, 1)
        for (long i = 0; i < (long)g_noutr; i++) {
            OutR *o = &g_outr[i];
            o->e1st = e1_count_big(d11, delta, y11, beta, o->tau, o->eps, ba, bb, &o->e1);
            double px = e1_exact(d11, delta, y11, beta, o->tau, o->eps, xa, xb);
            o->e1x = px < 0.0 ? -1.0 : px * exp2(3.0 * WBITS - __builtin_popcount(x5 & LOWBITS));
        }
        free(ba); free(bb); free(xa); free(xb);
    }
    return (long)nouts;
}

#ifndef RULE_NO_MAIN
int main(int argc, char **argv) {
    if (argc < 8) { fprintf(stderr, "usage: %s D3 D11 DELTA Y3 ETA BETAFILE Y11 [-rule SPEC]... [-mode auto|orig|proj|both] [-nox]\n", argv[0]); return 2; }
    u32 d3 = (u32)strtoul(argv[1], NULL, 16), d11 = (u32)strtoul(argv[2], NULL, 16), delta = (u32)strtoul(argv[3], NULL, 16);
    u32 y3 = (u32)strtoul(argv[4], NULL, 16), eta = (u32)strtoul(argv[5], NULL, 16), y11 = (u32)strtoul(argv[7], NULL, 16);
    for (int i = 8; i < argc; i++) {
        if (!strcmp(argv[i], "-rule") && i + 1 < argc) {
            if (g_nrule == MAXRULE || rule_parse(&g_rule[g_nrule], argv[++i])) { fprintf(stderr, "bad rule %s\n", argv[i]); return 2; }
            g_nrule++;
        } else if (!strcmp(argv[i], "-mode") && i + 1 < argc) {
            const char *m = argv[++i];
            g_mode = !strcmp(m, "orig") ? 1 : !strcmp(m, "proj") ? 2 : !strcmp(m, "both") ? 3 : 0;
        } else if (!strcmp(argv[i], "-nox")) g_usex = 0;
        else if (!strcmp(argv[i], "-cappairs") && i + 1 < argc) N3R_CAP_PAIRS = exp2(atof(argv[++i]));
        else if (!strcmp(argv[i], "-capb") && i + 1 < argc) N3R_CAP_B = exp2(atof(argv[++i]));
        else if (!strcmp(argv[i], "-capc") && i + 1 < argc) N3R_CAP_C = exp2(atof(argv[++i]));
        else if (!strcmp(argv[i], "-capwork") && i + 1 < argc) N3R_CAP_WORK = exp2(atof(argv[++i]));
        else if (!strcmp(argv[i], "-capx") && i + 1 < argc) N3X_CAP_WORK = exp2(atof(argv[++i]));
        else if (!strcmp(argv[i], "-cube") && i + 2 < argc) {
            u32 cm = (u32)strtoul(argv[i + 1], NULL, 16), cv = (u32)strtoul(argv[i + 2], NULL, 16);
            u32 x1c = rol(eta, ROT1), e1m = x1c & LOWBITS, e1v = ~(((d3 + x1c) & WMASK) >> 1) & e1m;
            if ((cm & e1m) != e1m || (cv & e1m) != e1v || (cv & ~cm)) {
                fprintf(stderr, "cube %08x/%08x is not inside the class %08x/%08x\n", cm, cv, e1m, e1v); return 2; }
            s_xmask = cm & ~e1m; s_xval = cv & s_xmask; i += 2;
        }
        else { fprintf(stderr, "unknown argument %s\n", argv[i]); return 2; }
    }
    if (ROTD != 1) { fprintf(stderr, "ROTD must be 1\n"); return 2; }
    g_nocut = getenv("H8_NOCUT") != NULL;
    FILE *bf = fopen(argv[6], "r");
    if (!bf) { perror(argv[6]); return 2; }
    int we = wtl(rol(eta, ROT1)) + __builtin_popcount(s_xmask);
    long double scale = ldexpl(1.0L, we - 3 * WBITS);
    printf("PIN d3 %08x d11 %08x delta %08x y3 %08x y11 %08x eta %08x fixed_bits %d rules %d mode %d nocut %d extra_mask %08x extra_value %08x\n",
           d3, d11, delta, y3, y11, eta, we, g_nrule, g_mode, g_nocut, s_xmask, s_xval);
    for (int r = 0; r < g_nrule; r++) {
        printf("RULE %d", r);
        for (int c = 0; c < g_rule[r].nc; c++) printf(" %08x:%d", g_rule[r].mask[c], g_rule[r].val[c]);
        printf("  outside_eta %08x\n", g_rule[r].support & ~(eta & LOWBITS) & WMASK);
    }
    char line[256], bstr[32];
    while (fgets(line, sizeof line, bf)) {
        if (sscanf(line, "%31s", bstr) != 1) continue;
        u32 beta = (u32)strtoul(bstr, NULL, 16);
        long rc = count_beta(d3, d11, delta, y3, y11, eta, beta);
        int k = wtl(rol(beta, ROT2));
        if (rc < 0) { printf("BETA %08x k %d %s\nDONE %08x\n", beta, k, rc == -1 ? "infeasible" : "noeps", beta); fflush(stdout); continue; }
        long n3pos = 0, prod = 0, notc = 0, proj = 0, e1bad = 0, xs = 0, xeq = 0, xdf = 0, beq = 0, bdf = 0, e1eq = 0, e1df = 0;
        long double part = 0.0L, pp[MAXRULE];
        for (int r = 0; r < MAXRULE; r++) pp[r] = 0.0L;
        for (size_t i = 0; i < g_noutr; i++) {
            const OutR *o = &g_outr[i];
            printf("OUTR %08x %08x %08x %08x E1 ", eta, beta, o->tau, o->eps);
            fput_big(stdout, o->e1);
            printf(" N3 "); fput_big(stdout, o->n3);
            printf(" P");
            for (int r = 0; r < g_nrule; r++) { fputc(' ', stdout); fput_big(stdout, o->pass[r]); }
            printf(" S %d %d M %d X %.17g %d B %d Z %.0f %.0f %.0f %.0f %.0f\n", o->n3st, o->e1st, o->fn, o->xn, o->xsampled, o->both,
                   o->ea, o->eb, o->maxnc, o->keys, o->surv);
            n3pos += o->n3 > 0; prod += (o->n3 > 0 && o->e1 > 0); notc += o->n3st != 0; proj += o->fn; e1bad += o->e1st != 0;
            if (o->xsampled > 0) xs++;
            else if (o->xsampled == 0 && o->n3st == 0) { if ((double)o->n3 == o->xn) xeq++; else xdf++; }
            if (o->both == 1) beq++; else if (o->both == 0) bdf++;
            if (o->e1st == 0 && o->e1x >= 0.0) {
                double d = (double)o->e1;
                if (fabs(d - o->e1x) <= 1e-9 * (d > 1.0 ? d : 1.0)) e1eq++; else e1df++;
            }
            part +=(long double)o->e1 * (long double)o->n3 * scale;
            for (int r = 0; r < g_nrule; r++) pp[r] += (long double)o->e1 * (long double)o->pass[r] * scale;
        }
        printf("BETA %08x k %d taus %llu passing %ld n3pos %ld prod %ld notcounted %ld proj %ld e1fallback %ld xsampled %ld xequal %ld xdiff %ld bothequal %ld bothdiff %ld e1equal %ld e1diff %ld part %.6Lf pass",
               beta, k, ntau, rc, n3pos, prod, notc, proj, e1bad, xs, xeq, xdf, beq, bdf, e1eq, e1df, part);
        for (int r = 0; r < g_nrule; r++) printf(" %.6Lf", pp[r]);
        printf("\nDONE %08x\n", beta);
        fflush(stdout);
    }
    fclose(bf);
    return 0;
}
#endif
